int FromWhile() { while (true) { return 11; } }
int FromFor() { for (; ; Print("unreachable")) { return 22; } }
int FromDo() { do { return 33; } while (false); }
int Nested() { for (;;) { while (true) { break; } return 44; } }
int Find(int target) { for (var i = 0; i < 5; i = i + 1) { if (i == target) return i; } return -1; }
int Search(bool again) { var i = 0; do { i = i + 1; if (again && i < 3) continue; return i; } while (true); }
void NeverCalled() { for (;;) continue; }
void Main() { Print(FromWhile()); Print(FromFor()); Print(FromDo()); Print(Nested()); Print(Find(3)); Print(Find(9)); Print(Search(true)); }
